class Cycle:
    def __init__(self, iterable):
        self.items = list(iterable)
        self.index = 0
    def __iter__(self):
        return self
    def __next__(self):
        if not self.items:
            raise StopIteration()
        val = self.items[self.index]
        self.index = (self.index + 1) % len(self.items)
        return val

