class Repeat:
    def __init__(self, value, times):
        self.value = value
        self.times = times
        self.count = 0
    def __iter__(self):
        return self
    def __next__(self):
        if self.count >= self.times:
            raise StopIteration()
        self.count += 1
        return self.value

