class TakeWhile:
    def __init__(self, predicate, iterable):
        self.predicate = predicate
        self.iter = iter(iterable)
        self.done = False
    def __iter__(self):
        return self
    def __next__(self):
        if self.done:
            raise StopIteration()
        item = next(self.iter)
        if self.predicate(item):
            return item
        self.done = True
        raise StopIteration()

